package com.example.foryou.data.local.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Represents a medicine entity in the database.
 *
 * @property id The unique identifier for the medicine, auto-generated by Room.
 * @property name The name of the medicine.
 * @property frequency How often the medicine should be taken (e.g., "Every day").
 * @property quantity The dosage or amount of the medicine (e.g., "1 pill", "10mg").
 * @property endDate The date until which the medicine should be taken (format: "yyyy-MM-dd").
 * @property notes Optional additional notes about the medicine.
 * @property userEmail The email of the user this medicine belongs to, acting as a foreign key.
 * @property creationDate The date the medicine was added (format: "yyyy-MM-dd").
 */
@Entity(tableName = "medicines")
data class Medicine(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val name: String,
    val frequency: String,
    val quantity: String,
    val endDate: String,
    val time: String,
    val notes: String?,
    val userEmail: String,
    val creationDate: String
)
